<?php $author = kimpu_public_author_data( get_the_author_meta( 'ID' ) ); if ( $author ) : ?><section class="post-author-box" aria-labelledby="author-box-title"><div class="post-author-avatar"><?php echo $author['avatar']; ?></div><div><h2 id="author-box-title"><?php echo esc_html( $author['name'] ); ?></h2><?php if ( $author['bio'] ) : ?><p><?php echo esc_html( $author['bio'] ); ?></p><?php endif; ?><?php if ( $author['url'] ) : ?><a href="<?php echo esc_url( $author['url'] ); ?>" rel="me noopener"><?php esc_html_e( 'Visit website', 'kimpu-multipurpose' ); ?></a><?php endif; ?><a class="text-link" href="<?php echo esc_url( $author['archive'] ); ?>"><?php esc_html_e( 'View all articles', 'kimpu-multipurpose' ); ?> →</a></div></section><?php endif; ?>
